import json, time, requests, redis

SLA_MAX_WAIT_SEC, COOLDOWN_SEC = 180, 900

def inspect_bullmq_queue(r: redis.Redis, queue_name: str) -> dict:
    prefix = f"bull:{queue_name}"
    oldest_age = 0
    oldest_id = r.lindex(f"{prefix}:wait", -1)
    if oldest_id:
        ts = r.hget(f"{prefix}:{oldest_id.decode()}", "timestamp")
        if ts: oldest_age = int(time.time() - int(ts) / 1000)
    return {
        "queue": queue_name, "wait": r.llen(f"{prefix}:wait"),
        "active": r.llen(f"{prefix}:active"), "failed": r.zcard(f"{prefix}:failed"),
        "dlq": r.llen(f"{prefix}:dlq"), "oldest_wait_age_sec": oldest_age,
    }

def send_zalobot_alert_if_needed(r: redis.Redis, stats: dict, webhook_url: str, secret: str) -> bool:
    breaches = []
    if stats["oldest_wait_age_sec"] > SLA_MAX_WAIT_SEC:
        breaches.append(f"Kẹt queue {stats['oldest_wait_age_sec']}s (> {SLA_MAX_WAIT_SEC}s)")
    if stats["failed"] >= 15 or stats["dlq"] >= 5:
        breaches.append(f"Tồn lỗi failed={stats['failed']}, dlq={stats['dlq']}")
    if not breaches or not r.set(f"obs:cooldown:{stats['queue']}", "1", ex=COOLDOWN_SEC, nx=True):
        return False
    msg = (f"[SRE ALERT] Queue `{stats['queue']}` bất thường: {' | '.join(breaches)}\n"
           f"wait={stats['wait']}, failed={stats['failed']}, dlq={stats['dlq']} -> Đã bật cờ STALE AI BI.")
    resp = requests.post(webhook_url, headers={"Authorization": f"Bearer {secret}"},
                         json={"channel": "sre-ops", "text": msg}, timeout=5)
    return resp.status_code == 200
